/* Inventory: the board (IN1, IN2), the item as a panel and as a page (IN3), the catalog and Unsorted (IN5, IN6). */
const ivAud = (a) => `<span class="aud">${ic(/GM/.test(a) ? 'private' : /Everyone/.test(a) ? 'eye' : 'kind-being')}${esc(a)}</span>`;
function card(i, ro) {
  const on = IV.sel === i.id; const picked = IV.picked.has(i.id); const movable = !ro && canMove(i);
  return `<div class="ivi ${on ? 'sel' : ''} ${ro ? 'ro' : ''}" ${movable && !IV.multi ? 'draggable="true"' : ''} data-it="${i.id}">${IV.multi && movable ? `<label class="ivck"><input type="checkbox" data-pick="${i.id}" ${picked ? 'checked' : ''} aria-label="Select ${esc(i.n)}"></label>` : ''}<button type="button" class="ivmain" data-iv="open" data-v="${i.id}" aria-pressed="${on}"><span class="ivn">${esc(i.n)}${i.q > 1 ? ` <span class="t-meta">× ${i.q}</span>` : ''}</span><span class="t-meta">${i.w ? `${wt(i)} lb` : ''}${i.owner !== i.at && i.owner !== (IV.board) ? '' : ''}${i.owner !== IV.board ? `${i.w ? ' · ' : ''}${esc(ownerN(i.owner))}’s` : ''}</span>${i.unsorted ? `<span class="ivb2">${ic('kind-item-unknown')}Unsorted</span>` : ''}</button><button type="button" class="icon-btn ivmore" data-iv="menu" data-v="${i.id}" aria-label="Actions for ${esc(i.n)}" aria-haspopup="menu" aria-expanded="false">${ic('more')}</button></div>`;
}
function colEl(c) {
  const w = sumw(c.all); const glow = !c.ro && (c.id === 'eq' || c.id === 'nc');
  const room = c.cap != null ? `${w} of ${c.cap} lb · ${c.cap - w > 0 ? `${fx(c.cap - w)} lb free` : 'full'}` : `${w} lb`;
  return `<section class="ivc ${c.ro ? 'ro' : ''} ${glow ? 'glow' : ''} ${IV.col === c.id ? 'active' : ''}" data-col="${c.id}" aria-labelledby="h-${c.id.replace(':', '-')}"><h2 id="h-${c.id.replace(':', '-')}" class="ivh"><span>${esc(c.n)}${c.ro ? ` <span class="ivro">${ic('private')}Read only</span>` : ''}</span><span class="t-meta num">${c.all.length}${c.items.length !== c.all.length ? ` (${c.items.length} shown)` : ''}</span></h2><p class="ivnote t-meta"><span class="num">${room}</span> · ${esc(c.note)}</p><div class="ivcards" role="group" aria-label="${esc(c.n)} cards" tabindex="-1">${c.items.map((i) => card(i, c.ro)).join('') || `<p class="t-meta">${IV.q ? 'Nothing here matches.' : 'Nothing here.'}</p>`}</div></section>`;
}
function bulkBar() {
  if (!IV.multi) return ''; const L = [...IV.picked].map(itemOf).filter(Boolean); const same = L.length > 1 && L.every((x) => sameStack(x, L[0]) || x === L[0]);
  return `<div class="ivbulk" role="region" aria-label="Selection"><b>${pl(L.length, 'card', 'cards')} selected</b><span class="grow"></span><button type="button" class="btn" data-iv="bmove" ${L.length ? '' : 'aria-disabled="true"'}>Move to…</button><button type="button" class="btn" data-iv="bgive" ${L.length ? '' : 'aria-disabled="true"'}>Give…</button><button type="button" class="btn" data-iv="bmerge" ${same ? '' : 'aria-disabled="true"'} ${same ? '' : 'title="Pick two or more stacks of the same item"'}>Merge</button><button type="button" class="btn" data-iv="bclear">Done</button></div>`;
}
function ivBoardPage() {
  const b = IV.board; const B = BOARDS[b]; const cols = colsOf(b); const all = ITEMS.filter((i) => i.at === b || i.owner === b);
  const cw = carriedW(b); const cap = 120;
  const tabs = `<div class="ivtabs" role="tablist" aria-label="Columns">${cols.map((c) => `<button type="button" role="tab" aria-selected="${IV.col === c.id}" data-iv="col" data-v="${c.id}">${esc(c.n)}<span class="t-meta num">${c.all.length}</span></button>`).join('')}</div>`;
  const empty = !all.length;
  return `<div class="page page-enter iv ivfill"><div class="head-row"><div class="grow"><div class="ivtitle"><button type="button" class="ivsw" id="iv-sw" data-iv="switch" aria-haspopup="menu" aria-expanded="false"><h1 class="t-title page-title" style="margin:0">${esc(B.n)}</h1>${ic('expand')}</button></div><p class="t-meta" style="margin:0">${B.kind} · what ${B.kind === 'Group' ? 'it' : B.kind === 'Nobody' ? 'nobody' : 'they'} control${B.kind === 'Nobody' ? 's' : ''}</p></div></div>
  <div class="toolbar ivtools"><div class="search">${ic('search')}<label class="sr-only" for="ivq">Search this board</label><input id="ivq" class="input" type="search" placeholder="Search this board" value="${esc(IV.q)}" autocomplete="off"></div><button type="button" class="btn" data-iv="add">${ic('add')}<span>Add an item</span></button>${isGM() ? `<button type="button" class="btn" data-iv="make">${ic('kind-item-add')}<span>Make from catalog</span></button>` : ''}<button type="button" class="btn" data-iv="multi" aria-pressed="${IV.multi}">${ic('select-mode')}<span>Select</span></button><span class="grow"></span>${B.cols.some((c) => c.carried) ? `<div class="ivmeter"><div class="row3"><span class="t-meta">Carried weight</span><span class="num t-meta" id="iv-cw">${cw} of ${cap} lb</span></div><div class="bar6" role="progressbar" aria-label="Carried weight" aria-valuemin="0" aria-valuemax="${cap}" aria-valuenow="${cw}"><i style="width:${Math.min(100, cw / cap * 100)}%"></i></div></div>` : ''}</div>${bulkBar()}
  ${empty ? `<div class="ivempty">${slot('empty-inventory', 'Nothing carried')}<p><b>Nothing here yet.</b></p><p class="t-meta">Add an item to start.</p><button type="button" class="btn btn--primary" data-iv="add">${ic('add')}<span>Add an item</span></button></div>` : `${tabs}<div class="ivsplit ${IV.sel && !isSmallI() ? 'with' : ''}"><div class="ivboard hmask" id="ivboard" role="region" aria-label="Board of ${esc(B.n)}" tabindex="0">${cols.map(colEl).join('')}</div>${IV.sel && !isSmallI() ? itemView(itemOf(IV.sel), 'panel') : ''}</div>`}</div>`;
}
const isSmallI = () => W() <= 1099;
/* the item: one content, in a panel or as a page (IN3) */
function itemView(it, mode) {
  if (!it) return '';
  const page = mode === 'page'; const c = it.cat ? catOf(it.cat) : null; const here = `${colN(it.at, it.col)}${it.at !== it.owner ? `, with ${ownerN(it.at)}` : ''}`;
  const notes = it.notes.filter((n) => isGM() || !/GM/.test(n.who));
  const edit = page && isGM();
  const acts = canMove(it) ? `<div class="ivacts"><button type="button" class="btn btn--primary" data-iv="move" data-v="${it.id}">Move to…</button><button type="button" class="btn" data-iv="give" data-v="${it.id}">Give…</button><button type="button" class="btn" data-iv="down" data-v="${it.id}">Set down</button><button type="button" class="btn" data-iv="note" data-v="${it.id}">Add a note</button>${it.q > 1 ? `<button type="button" class="btn" data-iv="split" data-v="${it.id}">Split</button>` : ''}${c && c.pack ? `<button type="button" class="btn" data-iv="unpack" data-v="${it.id}">Unpack</button>` : ''}</div>` : `<p class="t-meta ivro2">${ic('private')}This is in ${esc(ownerN(it.at))}’s ${esc(colN(it.at, it.col).toLowerCase())}. You can read it here and not move it.</p>`;
  const gmx = isGM() ? `<div class="ivgm"><h3 class="t-micro">GM</h3><div class="ivacts"><button type="button" class="btn" data-iv="reassign" data-v="${it.id}">Reassign…</button><button type="button" class="btn" data-iv="unassign" data-v="${it.id}">Unassign</button>${page ? '' : `<a class="btn" href="#/item/${it.id}">Edit the page</a>`}<button type="button" class="btn btn--danger" data-iv="delete" data-v="${it.id}">Delete…</button></div></div>` : '';
  const ownStats = edit ? `<dl class="ivdl"><div><dt><label for="st-w">Weight, lb each</label></dt><dd><input id="st-w" class="input sm num" inputmode="decimal" data-st="w" value="${it.w}"></dd></div></dl>` : `<dl class="ivdl"><div><dt>Weight</dt><dd class="num">${it.w} lb${it.q > 1 ? ` each, ${wt(it)} lb in all` : ''}</dd></div>${c ? `<div><dt>Value</dt><dd class="num">${c.v}</dd></div>` : ''}</dl>`;
  return `<aside class="ivp ${page ? 'page' : ''}" aria-label="${esc(it.n)}"><div class="ivph">${ic('kind-item')}<h2 class="t-sec">${esc(it.n)}</h2>${page ? `<button type="button" class="btn sm" data-iv="copy">${ic('copy')}<span>Copy link</span></button>` : `<button type="button" class="icon-btn" data-iv="closep" aria-label="Close the panel">${ic('close')}</button>`}</div>
  <p class="t-meta">${it.q > 1 ? `${it.q} of them` : 'One'} · ${wt(it)} lb · ${esc(here)} · ${esc(ownerN(it.owner))}’s${it.unsorted ? ' · <span class="ivb2">Unsorted</span>' : ''}</p>
  ${edit && c ? `<h3 class="t-micro">Description <span class="t-meta">saves as you type</span></h3><div class="ivinl" id="iv-desc" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Description">${esc(c.desc)}</div><p class="t-meta ivsv" role="status"><span id="iv-saved"></span></p>` : c ? `<p>${esc(c.desc)}</p>` : '<p class="muted">No description yet.</p>'}
  ${acts}${gmx}${ownStats}
  ${c ? `<h3 class="t-micro">Made from</h3><p>${c.protos.map((p) => `<span class="tag">${esc(p)}</span>`).join(' ')}</p>` : ''}
  <h3 class="t-micro">Notes</h3>${notes.length ? `<ul class="ivnl">${notes.map((n) => `<li>${ivAud(n.who)}<p>${esc(n.t)}</p></li>`).join('')}</ul>` : '<p class="t-meta">No notes you can read.</p>'}
  ${page ? '' : `<a class="ivopen" href="#/item/${it.id}">Open the page ${ic('next')}</a>`}</aside>`;
}
function pItem() {
  const it = itemOf(parts()[1]);
  if (!it) return `<div class="page page--wide page-enter iv"><div class="ivempty"><p><b>This page does not exist.</b></p><p class="t-meta">The link may be wrong, or the item is not one you can read.</p><a class="btn" href="#/board">Back to the board</a></div></div>`;
  return `<div class="page page--wide page-enter iv"><p class="t-meta"><a href="#/board">${ic('back')} Back to ${esc(ownerN(it.at))}’s board</a></p><div class="ivsplit one">${itemView(it, 'page')}</div></div>`;
}
/* ---- catalog */
const catList = () => CAT.filter((c) => !IV.cq || c.n.toLowerCase().includes(IV.cq.toLowerCase()));
function catPanel(c) {
  const made = ITEMS.filter((i) => i.cat === c.id).length; const dirty = IV.catSave && IV.catSave.id === c.id ? IV.catSave : null; const f = dirty || c;
  return `<aside class="ivp" aria-label="${esc(c.n)}"><div class="ivph">${ic('kind-item')}<h2 class="t-sec">${esc(c.n)}</h2><span class="t-meta">${pl(made, 'made', 'made')}</span></div>
  ${isGM() ? `<h3 class="t-micro">Description <span class="t-meta">saves as you type</span></h3><div class="ivinl" id="iv-cdesc" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Description">${esc(c.desc)}</div><p class="t-meta ivsv" role="status"><span id="iv-saved"></span></p>
  <dl class="ivdl"><div><dt><label for="cw">Weight, lb</label></dt><dd><input id="cw" class="input sm num" inputmode="decimal" data-cst="w" value="${c.w}"></dd></div><div><dt><label for="cv">Value</label></dt><dd><input id="cv" class="input sm num" inputmode="decimal" data-cst="v" value="${c.v}"></dd></div></dl>
  <h3 class="t-micro">Tags</h3><div class="ivtags">${['Light', 'Fragile', 'Weapon', 'Medical', 'Food', 'Cord', 'Pack', 'Money'].map((t) => `<button type="button" class="ivtg" data-iv="ctag" data-v="${t}" aria-pressed="${c.tags.includes(t)}">${t}</button>`).join('')}</div>
  <fieldset class="ivfs"><legend class="t-micro">Structure <span class="t-meta">kept with Save changes</span></legend><label class="label" for="cl">Link name</label><input id="cl" class="input" data-fld="slug" value="${esc(f.slug)}" aria-describedby="clh"><p class="t-meta" id="clh">Links to [[${esc(c.n)}]] find the item by this name.</p><label class="label" for="cp">Made from</label><input id="cp" class="input" data-fld="protos" value="${esc(f.protos.join(', '))}"><label class="ivrd"><input type="checkbox" data-fld="public" ${f.public ? 'checked' : ''}> In the public catalog</label></fieldset>
  <div class="ivacts"><button type="button" class="btn" data-iv="make" data-v="${c.id}">${ic('kind-item-add')}<span>Make one…</span></button><button type="button" class="btn" data-iv="used" data-v="${c.id}">Used as a prototype by ${CAT.filter((x) => x.protos.includes(c.n)).length}</button><button type="button" class="btn btn--danger" data-iv="cdelete" data-v="${c.id}">Delete…</button></div>`
  : `<p>${esc(c.desc)}</p><dl class="ivdl"><div><dt>Weight</dt><dd class="num">${c.w} lb</dd></div><div><dt>Value</dt><dd class="num">${c.v}</dd></div></dl><p>${c.tags.map((t) => `<span class="tag">${t}</span>`).join(' ')}</p>`}</aside>`;
}
const saveBar = () => { const dirty = IV.catSave; return dirty ? `<div class="savebar2" role="region" aria-label="Unsaved changes"><span>${dirty.n} change${dirty.n === 1 ? '' : 's'} not saved</span><span class="grow"></span><button type="button" class="btn" data-iv="discard">Discard</button><button type="button" class="btn btn--primary" data-iv="save">Save changes</button></div>` : ''; };
function pCatItem() { const c = catOf(parts()[1]); if (!c) return `<div class="page page--wide page-enter iv"><div class="ivempty"><p><b>This page does not exist.</b></p><a class="btn" href="#/catalog">Back to the catalog</a></div></div>`; IV.cat = c.id; return `<div class="page page--wide page-enter iv"><p class="t-meta"><a href="#/catalog">${ic('back')} Back to the catalog</a></p><div class="ivsplit one">${catPanel(c)}</div>${saveBar()}</div>`; }
function pCatalog() {
  const L = catList(); const c = catOf(IV.cat) || L[0];
  const rows = L.map((x) => `<div role="row" class="ivrow ${c && x.id === c.id ? 'sel' : ''}"><span role="cell"><button type="button" class="ivlink" data-iv="cat" data-v="${x.id}"><b>${esc(x.n)}</b></button><span class="t-meta">${esc(x.kind)}</span></span><span role="cell">${x.public ? '<span class="everyone">Public</span>' : ivAud('GM only')}</span><span role="cell" class="num r t-meta">${ITEMS.filter((i) => i.cat === x.id).length} made</span></div>`).join('');
  return `<div class="page page--wide page-enter iv"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Catalog</h1><p class="page-sub">${isGM() ? 'What can be made' : 'What you can browse'} in ${esc(lib())}.</p></div>${isGM() ? `<button type="button" class="btn btn--primary" data-iv="newcat">${ic('add')}<span>New item</span></button>` : ''}</div><div class="toolbar"><div class="search">${ic('search')}<label class="sr-only" for="cq">Search the catalog</label><input id="cq" class="input" type="search" placeholder="Search the catalog" value="${esc(IV.cq)}" autocomplete="off"></div></div>
  <div class="ivsplit ${c && !isSmallI() ? 'with' : ''}"><div role="table" aria-label="Catalog" class="ivlist">${rows || '<p class="t-meta" style="padding:var(--s-3)">Nothing matches.</p>'}</div>${c && !isSmallI() ? catPanel(c) : ''}</div>
  ${saveBar()}</div>`;
}
/* ---- unsorted (GM) */
const unsGroups = () => { const m = {}; ITEMS.filter((i) => i.unsorted).forEach((i) => { (m[i.uname] = m[i.uname] || []).push(i); }); return m; };
function unsPanel(g, tick, sugg) { return `<aside class="ivp" aria-label="${esc(IV.uns)}"><div class="ivph"><h2 class="t-sec">${esc(IV.uns)}</h2><span class="t-meta">${pl(g.length, 'holder', 'holders')}</span></div><ul class="ivnl">${g.map((i) => `<li><label class="ivrd"><input type="checkbox" data-tick="${i.id}" ${tick.has(i.id) ? 'checked' : ''}> <b>${esc(ownerN(i.owner))}</b> · ${i.q}</label>${i.notes.map((n) => `<p class="t-meta">“${esc(n.t)}”</p>`).join('')}</li>`).join('')}</ul>
  <h3 class="t-micro" id="sg">It looks like</h3><div role="radiogroup" aria-labelledby="sg" class="ivsugs">${sugg.map((s) => `<button type="button" role="radio" class="ivsug" aria-checked="${IV.unsPick === s.id}" data-iv="pick" data-v="${s.id}"><b>${esc(catOf(s.id).n)}</b><span class="t-meta">${esc(s.why)}</span></button>`).join('') || '<p class="t-meta">Nothing alike. Search the catalog, or make a new item.</p>'}</div>
  <label class="label" for="uq">Or search the catalog</label><select id="uq" class="select" data-iv-sel="pickc"><option value="">Choose an item…</option>${CAT.map((c) => `<option value="${c.id}" ${IV.unsPick === c.id ? 'selected' : ''}>${esc(c.n)}</option>`).join('')}</select>
  <div class="ivacts"><button type="button" class="btn btn--primary" data-iv="match" ${IV.unsPick ? '' : 'aria-disabled="true"'}>Give the ticked to ${IV.unsPick ? esc(catOf(IV.unsPick).n) : 'an item'}</button><button type="button" class="btn" data-iv="makecat">Make a new catalog item</button><button type="button" class="btn" data-iv="keep">Keep for now</button></div></aside>`; }
function pUnsorted() {
  const G = unsGroups(); const names = Object.keys(G);
  if (!names.length) return `<div class="page page--wide page-enter iv"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Unsorted</h1></div></div><div class="ivempty"><p><b>Nothing to sort.</b></p><p class="t-meta">Things players write in by hand show up here until you match them to the catalog.</p></div></div>`;
  if (!G[IV.uns]) IV.uns = names[0];
  const rows = names.map((n) => `<div role="row" class="ivrow ${n === IV.uns ? 'sel' : ''}"><span role="cell"><button type="button" class="ivlink" data-iv="uns" data-v="${esc(n)}"><b>${esc(n)}</b></button><span class="t-meta">${G[n].map((i) => ownerN(i.owner)).join(', ')}</span></span><span role="cell" class="num r">${pl(G[n].reduce((a, i) => a + i.q, 0), 'item', 'items')}</span></div>`).join('');
  const g = G[IV.uns]; const tick = IV.unsTick || new Set(g.map((i) => i.id)); const sugg = unsSuggest(IV.uns);
  return `<div class="page page--wide page-enter iv"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Unsorted</h1><p class="page-sub">Things players wrote in that the catalog does not have yet.</p></div></div><div class="ivsplit ${isSmallI() ? '' : 'with'}"><div role="table" aria-label="Unsorted things" class="ivlist">${rows}</div>${isSmallI() ? '' : unsPanel(g, tick, sugg)}</div></div>`;
}
function unsSuggest(name) {
  const out = []; const k = name.toLowerCase(); if (SPELL[k]) out.push({ id: SPELL[k], why: `another way of writing “${name}”` });
  CAT.forEach((c) => { if (!out.some((o) => o.id === c.id) && (c.n.toLowerCase().includes(k.split(' ')[0]) || k.includes(c.n.toLowerCase().split(',')[0]))) out.push({ id: c.id, why: 'alike by name' }); });
  return out;
}

function pUnsItem() { const G = unsGroups(); const name = decodeURIComponent(parts()[1] || ''); if (!G[name]) return `<div class="page page--wide page-enter iv"><div class="ivempty"><p><b>Nothing to sort here.</b></p><a class="btn" href="#/unsorted">Back to Unsorted</a></div></div>`; IV.uns = name; const g = G[name]; const tick = IV.unsTick || new Set(g.map((i) => i.id)); return `<div class="page page--wide page-enter iv"><p class="t-meta"><a href="#/unsorted">${ic('back')} Back to Unsorted</a></p><div class="ivsplit one">${unsPanel(g, tick, unsSuggest(name))}</div></div>`; }
